{
  "name": "@openprojectx/opencode-kimi-auth",
  "version": "0.3.0",
  "description": "Kimi Code (subscription) OAuth login for opencode — RFC 8628 device flow for the kimi-for-coding provider (Kimi K3 / K2.7 Code)",
  "license": "MIT",
  "type": "module",
  "publishConfig": {
    "access": "public"
  },
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "kimi",
    "kimi-for-coding",
    "moonshot",
    "oauth"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "version-packages": "changeset version",
    "release": "bun run typecheck && bun test && changeset publish"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@changesets/cli": "^2.29.0",
    "@opencode-ai/plugin": "^1.18.23",
    "@types/node": "^24.0.0",
    "bun-types": "^1.3.0",
    "typescript": "^5.9.0"
  }
}
